INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (242,'zhTW','暫無內容','你好，$c。我們沒多少時間了。龍喉氏族的獸人們已經在靠近南方的大峽谷構築了自己的工事。$B$B他們拒絕執行酋長的命令，因此我們別無選擇，只能消滅他們，讓他們永遠不再玷汙部落的名字。','殺掉8個龍喉襲擊者、3個龍喉白骨守衛和1個龍喉軍官。','','Return to [UNUSED] Truek.','','','','',0);
