INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (259,'zhTW','<UNUSED>','你好啊，$n。久仰你的大名，能見到你真是我的榮幸。我猜你大概沒聽過老凱特的故事吧？啊，老凱特——也就是凱特·湯瑪辛——曾經被公認為全境最頂尖的獵人之一。他幾乎沒有什麼是沒做過的，可是有一天，他卻迷上了一個古老的傳說……說穿了不過是個神話罷了。傳說中，湖水深處住著一隻巨大的鰭龍。要我說，這根本是胡說八道。如果你有興趣的話，不妨去找凱特聊聊。','去找凱特·湯瑪辛談談。','','','','','','',0);
