INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (352,'zhTW','<UNUSED>','偉大的瑪莫達啊。她體型龐大，爪子和牙齒銳利如劍。當時我毫無防備，不過就算有所準備，恐怕也於事無補。她只是一揮爪——咻！眼前一片黑暗。他們都說我現在還能走路已經算走運了……$B$B唉，聽這種陳年往事想必也沒什麼樂趣可言吧？總之，$n，如果你想親自會會她——那位湖中夫人的話，','','','','','','','',0);
