INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (462,'zhTW','<UNUSED>','除了你以外，我們還派了兩名斥候穿越阿爾加茲。可是只有一人回來了。以下是他打探到的消息：$B$B龍喉氏族派出了他們的一名副官——馬魯克·龍鱗，到阿爾加茲去集結一支獸人隊伍，企圖切斷通往米奈希爾港的陸路！$B$B我們必須馬上阻止這件事。除掉馬魯克，然後向米奈希爾港的瓦斯塔格·鐵顎回報。$B$B馬魯克的據點是阿爾加茲第二和第三條隧道之間、一座池塘對岸的小洞穴。要前往米奈希爾，穿過阿爾加茲後沿著道路向西走即可。','殺死馬魯克·龍鱗$B$B向米奈希爾港的瓦斯塔格·鐵顎回報。','','去溼地找巴拉丁海灣的瓦斯塔格·鐵顎。','','','','',0);
