INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13649,'zhTW','賈斯汀的趣味測試','喂！看起來啤酒難不倒你。但你能好好使用啤酒杯嗎？$B$B黑鐵矮人要回來報復，毀掉我們的節慶。拿酒杯丟他們是最好的阻止方法，但首先，讓我們瞧瞧你能不能在老S.T.O.U.T.這裡丟中一個。$B$B這很簡單，拿起一杯免費招待的啤酒節樣品，然後幹了它。接下來要確定你面對著S.T.O.U.T.。等你丟中他5次之後再告訴我。','使用免費招待的啤酒節樣品並丟中S.T.O.U.T.5次，然後和博克西·栓旋者談談。','','Return to [PH] Justin\'s Test NPC.','S.T.O.U.T. Hit','','','',0);
